  const bucket = Math.min(90, Math.floor(ang / 10) * 10);
  foldHist.set(bucket, (foldHist.get(bucket) || 0) + 1);
  if (ang > 60) foldOver[60]++;
  if (ang > 80) foldOver[80]++;
  if (ang > 89) foldOver[89]++;
}
