419	    this.ranks = new Uint8Array(size);
420	  }
421	
422	  find(index) {
423	    let root = index;
424	    while (this.parents[root] !== root) root = this.parents[root];
425	    while (this.parents[index] !== index) {
426	      const parent = this.parents[index];
427	      this.parents[index] = root;
428	      index = parent;
429	    }
430	    return root;
431	  }
432	
433	  union(left, right) {
434	    let leftRoot = this.find(left);
435	    let rightRoot = this.find(right);
436	    if (leftRoot === rightRoot) return;
437	    if (this.ranks[leftRoot] < this.ranks[rightRoot]) [leftRoot, rightRoot] = [rightRoot, leftRoot];
438	    this.parents[rightRoot] = leftRoot;
439	    if (this.ranks[leftRoot] === this.ranks[rightRoot]) this.ranks[leftRoot] += 1;
440	  }
441	}

